CREATE POLICY "region.admin can update region_invitations" ON "region_invitations" AS PERMISSIVE FOR UPDATE TO "authenticated" USING ((SELECT authorize_in_region('region.admin', region_fk))) WITH CHECK ((SELECT authorize_in_region('region.admin', region_fk)));--> statement-breakpoint
CREATE POLICY "region members can read region_invitations" ON "region_invitations" AS PERMISSIVE FOR SELECT TO "authenticated" USING ((SELECT authorize_in_region('region.read', region_fk)));--> statement-breakpoint
CREATE POLICY "users can read own region_invitations" ON "region_invitations" AS PERMISSIVE FOR SELECT TO "authenticated" USING ((SELECT auth.jwt() ->> 'email') = email);--> statement-breakpoint
CREATE POLICY "users can update own region_invitations" ON "region_invitations" AS PERMISSIVE FOR UPDATE TO "authenticated" USING ((SELECT auth.jwt() ->> 'email') = email) WITH CHECK ((SELECT auth.jwt() ->> 'email') = email);--> statement-breakpoint
CREATE POLICY "region.admin can manage region_members" ON "region_members" AS PERMISSIVE FOR ALL TO "authenticated" USING ((SELECT authorize_in_region('region.admin', region_fk))) WITH CHECK ((SELECT authorize_in_region('region.admin', region_fk)));--> statement-breakpoint
CREATE POLICY "region.admin can update regions they administer" ON "regions" AS PERMISSIVE FOR UPDATE TO "authenticated" USING ((SELECT authorize_in_region('region.admin', regions.id))) WITH CHECK ((SELECT authorize_in_region('region.admin', regions.id)));